  $('notes-sheet-form').addEventListener('submit',event=>{event.preventDefault();if(busy)return;const input={...sheetDraft,name:$('notes-sheet-name').value,areaId:$('notes-sheet-area').value||null,expectedVersion:sheetDraft.version};run(async()=>{const result=await api.saveSheet(input);sheetId=result.result.id;const nextArea=result.document.sheets.find(sheet=>sheet.id===sheetId).areaId||'ungrouped';if(areaId!==nextArea)masterId=null;areaId=nextArea;clearChecks();$('notes-sheet-dialog').close();return result;},'已儲存表格與欄位。');});
  $('notes-record-form').addEventListener('submit',event=>{event.preventDefault();if(busy)return;setFormTab('basic');if(typeof $('notes-record-form').reportValidity==='function'&&!$('notes-record-form').reportValidity()){saveAndNew=false;return;}const again=saveAndNew,target=editingRecord.sheetId;saveAndNew=false;const input={id:editingRecord.id,sheetId:editingRecord.sheetId,expectedVersion:editingRecord.version,title:$('notes-record-title').value,notes:$('notes-record-body').value,tags:$('notes-record-tags').value.split(/[,，]/).map(value=>value.trim()).filter(Boolean),values:Object.fromEntries(fieldGetters.map(field=>[field.id,field.get()])),favoriteIds:[...selectedFavorites],keepUnlinked:[...unlinkedPaths],favoriteTags:[...selectedFavoriteTags],keepPendingTags:pendingFavoriteTags};run(async()=>{const result=await api.saveRecord(input);finishRecord(result,prefs().notesOpenAfterSave||Boolean(editingRecord.id&&recordId===editingRecord.id));$('notes-record-dialog').close();return result;},'已儲存紀錄').then(result=>{if(result&&again)editRecord(null,target);});});
  $('notes-pick-favorites').addEventListener('click',()=>openLinkPicker());$('notes-favorites-apply').addEventListener('click',()=>{const paths=favoritePicker.value(),tags=favoriteTagPicker.value();if(paths.length>100||tags.length>20){callbacks.showFailure('連結數量過多','最多 100 個位置及 20 個收藏標籤');return;}const pending=pendingFavoriteTags.filter(tag=>!tags.some(value=>value.toLocaleLowerCase()===tag.toLocaleLowerCase()));if(tags.length+pending.length>20){callbacks.showFailure('連結數量過多','最多 20 個收藏標籤，請移除部分分享標籤');return;}selectedFavorites=new Set(paths);selectedFavoriteTags=new Set(tags);pendingFavoriteTags=pending;renderRecordFiles();$('notes-favorites-dialog').close();});
  $('notes-restore-backup').addEventListener('click',()=>openTransfer('restore'));$('notes-export').addEventListener('click',()=>openTransfer('export'));$('notes-import').addEventListener('click',()=>openTransfer('import'));$('notes-transfer-cancel').addEventListener('click',()=>$('notes-transfer-dialog').close());for(const id of ['notes-export-scope','notes-export-related','notes-import-mode'])$(id).addEventListener('change',invalidateTransfer);
