  $('notes-transfer-preview').addEventListener('click',()=>run(async()=>{if(transferKind==='import'&&!importChosen)throw new Error('請先選取資料包');const scope=$('notes-export-scope').value;transferData=transferKind==='restore'?await api.chooseBackup():transferKind==='export'?await api.exportPreview({scope,id:scope==='area'?areaId:scope==='sheet'?sheetId:scope==='record'?recordId:undefined,related:$('notes-export-related').checked}):await api.importPreview($('notes-import-mode').value);if(transferData.canceled)return;transferToken=transferData.token;transferPage=0;renderTransfer();$('notes-transfer-summary').textContent=transferKind==='restore'?`將完整還原「${transferData.name}」的 ${transferData.records.length} 筆紀錄；目前資料會先另存備份。`:transferKind==='export'?`將匯出 ${transferData.records.length} 筆紀錄、${transferData.links} 個檔案位置、${transferData.tagLinks||0} 個收藏標籤連結；${transferData.omittedRelations} 個未包含的關聯已省略。`:`新增 ${transferData.added} 筆、更新 ${transferData.updated} 筆、略過 ${transferData.skipped} 筆；更新會覆蓋同識別碼的筆記、欄位及連結。檔案位置需在本機重新連結；${transferData.tagLinks||0} 個收藏標籤連結也須重新確認。`;$('notes-transfer-apply').disabled=false;},'資料包預覽完成。'));
  $('notes-transfer-apply').addEventListener('click',()=>run(async()=>{if(!transferToken)throw new Error('請先預覽');if(transferKind==='export'){const result=await api.exportSave(transferToken);if(!result.canceled){$('notes-transfer-dialog').close();callbacks.showToast('已匯出：'+result.path);}return;}const result=await (transferKind==='restore'?api.restoreBackup(transferToken):api.importCommit(transferToken));$('notes-transfer-dialog').close();sheetId=null;recordId=null;callbacks.showToast((transferKind==='restore'?'還原完成，操作前備份：':'匯入完成，備份：')+result.result.backup);return result;},'資料包操作完成。'));
  $('notes-transfer-search').addEventListener('input',()=>{transferPage=0;renderTransfer();});$('notes-transfer-prev').addEventListener('click',()=>{transferPage--;renderTransfer();});$('notes-transfer-next').addEventListener('click',()=>{transferPage++;renderTransfer();});
